/**
 * emit to subscription queries of type FindUnderwriter,
 * but only if the id matches
 *
 * @param		entity	Underwriter
 */
	protected void emitFindUnderwriter( Underwriter entity ) {
		LOGGER.info("handling emitFindUnderwriter" );
		
	    queryUpdateEmitter.emit(FindUnderwriterQuery.class,
	                            query -> query.getFilter().getUnderwriterId().equals(entity.getUnderwriterId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllUnderwriter
	 * 
	 * @param		entity	Underwriter
	 */
	protected void emitFindAllUnderwriter( Underwriter entity ) {
		LOGGER.info("handling emitFindAllUnderwriter" );
		
	    queryUpdateEmitter.emit(FindAllUnderwriterQuery.class,
	                            query -> true,
	                            entity);
	}

